int main() {
    double w = 0; int segok = 1;
    int fail_rec = !(recip_sweep() <= 1e-10);
    int fail_dec = 0;
    fail_dec |= hy_region(1.0, -1.0, 1.0) != 0;
    fail_dec |= hy_region(1.0000000000002274, -1.0, 1.0) != 1;
    fail_dec |= hy_region(-1.0, -1.0, 1.0) != 0;
    fail_dec |= hy_region(-1.0000000000002274, -1.0, 1.0) != 2;
    fail_dec |= hy_region(0.0, -1.0, 1.0) != 0;
    fail_dec |= hy_freeze(1.0, 1, 0, -1.0, 1.0) != 1;
    fail_dec |= hy_freeze(1.0, 0, 0, -1.0, 1.0) != 0;
    fail_dec |= hy_freeze(1.0, 0, 1, -1.0, 1.0) != 0;
    fail_dec |= hy_freeze(-1.0, 0, 1, -1.0, 1.0) != 1;
    fail_dec |= hy_freeze(-1.0, 0, 0, -1.0, 1.0) != 0;
    fail_dec |= hy_freeze(-1.0, 1, 0, -1.0, 1.0) != 0;
    fail_dec |= hy_freeze(0.5, 1, 0, -1.0, 1.0) != 0;
    printf("hy_region / hy_freeze with exact inputs: %s\n", fail_dec ? "FAIL" : "ok");
    int fail_cor = 0; double wc = 0;
    for (const Corner &c : CORNERS) {
        HydroCoefs k = *COEFS[c.unit - 1];   // a copy: the step takes non-const arrays
        St x[4]; Small r[4]; Sig u[1]; Pw y[1]; int md[3];
        for (int i = 0; i < 4; i++) { x[i] = c.x[i]; r[i] = 0; }
        u[0] = c.om;
        hydro_step(x, r, u, y, md, k.P, k.W, k.K, k.EX, k.EA, k.kc, k.kb, k.kw);
        double e = 0;
        if (c.fl == 0) {
            for (int i = 0; i < 4; i++) e = fmax(e, fabs(x[i].to_double() - c.ref[i]) / 10.0);
            e = fmax(e, fabs(y[0].to_double() - c.ref[4]) / 10.0);
            wc = fmax(wc, e);
        }
        if (md[0] != c.bk || md[1] != c.fl || md[2] != c.cr || !(e <= 5.0e-8)) {
            fail_cor = 1; printf("corner %s: bank %d flag %d crossing %d (expected %d %d %d), difference %.3e\n", c.name, md[0], md[1], md[2], c.bk, c.fl, c.cr, e);
        }
    }
    printf("corner suite: %d corners, max relative difference %.3e, banks / flags / crossings %s\n", (int)(sizeof(CORNERS) / sizeof(Corner)), wc, fail_cor ? "FAIL" : "as expected");
    w = fmax(w, run_case("A", HYDRO_COEFS_1, X0, US_A, DU_A, ON_A, MID_A, OFF_A, NC_A, CUTS_A, J_A, &segok));
    w = fmax(w, run_windows("A", HYDRO_COEFS_1, X0, US_A, DU_A, ON_A, MID_A, OFF_A, NW_A, WS_A, WK_A, WE_A, WJ_A, &segok));
    w = fmax(w, run_case("B", HYDRO_COEFS_1, X0, US_B, DU_B, ON_B, MID_B, OFF_B, NC_B, CUTS_B, J_B, &segok));
    w = fmax(w, run_windows("B", HYDRO_COEFS_1, X0, US_B, DU_B, ON_B, MID_B, OFF_B, NW_B, WS_B, WK_B, WE_B, WJ_B, &segok));
    int fail = !(w <= 5.0e-8) || !segok || fail_rec || fail_dec || fail_cor;
    printf("C sim check: max relative difference %.3e (limit %.0e), continuous = segmented %s, reciprocal %s, decisions %s, corners %s: %s\n",
           w, 5.0e-8, segok ? "yes" : "NO", fail_rec ? "FAIL" : "ok", fail_dec ? "FAIL" : "ok", fail_cor ? "FAIL" : "ok", fail ? "FAIL" : "PASS");
    return fail;
}
